// src/components/common/TransactionForm.jsx
import React, { useRef, useState } from 'react';
import './TransactionForm.css';

const TransactionForm = ({ 
  title, 
  isReplacement, 
  txData, 
  onChange, 
  onSubmit, 
  onCancel,
  isPending = false,
  representative
}) => {
  const fileInputRef = useRef(null);
  const [fileName, setFileName] = useState('No file chosen');
  const [fileError, setFileError] = useState('');

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) {
      setFileName('No file chosen');
      setFileError('');
      onChange({ target: { name: 'screenshot', value: null } });
      return;
    }

    // Validate file size (max 5MB)
    if (file.size > 5 * 1024 * 1024) {
      setFileError('File size must be less than 5MB');
      setFileName('No file chosen');
      fileInputRef.current.value = '';
      onChange({ target: { name: 'screenshot', value: null } });
      return;
    }

    // Validate file type
    const allowedTypes = ['image/jpeg', 'image/png', 'image/jpg', 'image/webp'];
    if (!allowedTypes.includes(file.type)) {
      setFileError('Only JPEG, PNG, JPG, and WEBP files are allowed');
      setFileName('No file chosen');
      fileInputRef.current.value = '';
      onChange({ target: { name: 'screenshot', value: null } });
      return;
    }

    setFileName(file.name);
    setFileError('');
    
    // Convert to base64 for preview
    const reader = new FileReader();
    reader.onloadend = () => {
      onChange({ 
        target: { 
          name: 'screenshot', 
          value: {
            file: file,
            base64: reader.result,
            name: file.name,
            size: file.size,
            type: file.type
          }
        } 
      });
    };
    reader.readAsDataURL(file);
  };

  const handleFileButtonClick = () => {
    fileInputRef.current.click();
  };

  const removeFile = () => {
    fileInputRef.current.value = '';
    setFileName('No file chosen');
    setFileError('');
    onChange({ target: { name: 'screenshot', value: null } });
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    onChange({ target: { name, value } });
  };

  // Get screenshot preview
  const getScreenshotPreview = () => {
    if (txData.screenshot && txData.screenshot.base64) {
      return txData.screenshot.base64;
    }
    return null;
  };

  return (
    <div className="claim-card transaction-container">
      <div className="transaction-title">{title}</div>
      <div className="tx-form">
        {isPending ? (
          <div className="field">
            <label>Transaction Amount</label>
            <div className="status-pending">⏳ Pending (Customer Care)</div>
            <div className="helper-text">Customer care will fill the amount</div>
          </div>
        ) : isReplacement ? (
          <div className="field">
            <label>Transaction Amount *</label>
            <input
              type="text"
              name="amount"
              value={txData.amount}
              onChange={handleInputChange}
              placeholder="e.g., 250000"
              required
            />
          </div>
        ) : (
          <div className="field">
            <label>Transaction Amount</label>
            <div className="status-pending">Amount Pending (Customer Care)</div>
          </div>
        )}
        
        <div className="field">
          <label>Transaction ID *</label>
          <input
            type="text"
            name="txId"
            value={txData.txId}
            onChange={handleInputChange}
            placeholder="TX-12345"
            required
          />
        </div>
        
        <div className="field">
          <label>Transaction Screenshot *</label>
          <div className="file-upload-wrapper">
            <div className="file-input" onClick={handleFileButtonClick}>
              <i className="fas fa-cloud-upload-alt"></i>
              <span className="file-label">{fileName}</span>
              {txData.screenshot && (
                <button 
                  type="button" 
                  className="file-remove-btn"
                  onClick={(e) => {
                    e.stopPropagation();
                    removeFile();
                  }}
                >
                  <i className="fas fa-times"></i>
                </button>
              )}
            </div>
            <input
              ref={fileInputRef}
              type="file"
              name="screenshot"
              accept="image/jpeg,image/png,image/jpg,image/webp"
              onChange={handleFileChange}
              style={{ display: 'none' }}
            />
            {fileError && <div className="file-error">{fileError}</div>}
            <div className="helper-text">Supported formats: JPEG, PNG, JPG, WEBP (Max 5MB)</div>
          </div>
          
          {/* Screenshot Preview */}
          {getScreenshotPreview() && (
            <div className="screenshot-preview">
              <img 
                src={getScreenshotPreview()} 
                alt="Transaction Screenshot" 
                className="preview-image"
              />
              <div className="preview-info">
                <span>{txData.screenshot?.name}</span>
                <span>{(txData.screenshot?.size / 1024).toFixed(2)} KB</span>
              </div>
            </div>
          )}
        </div>
        
        <div className="field">
          <label>Transaction Date</label>
          <input
            type="text"
            name="date"
            value={txData.date}
            readOnly
            className="readonly"
          />
        </div>
        
        <div className="field">
          <label>Representative</label>
          <input
            type="text"
            value={representative || 'Shabani'}
            disabled
            className="readonly"
          />
        </div>
        
        <div className="form-actions">
          <button type="button" className="btn-outline" onClick={onCancel}>Cancel</button>
          <button 
            type="button" 
            className="submit-btn" 
            onClick={onSubmit}
            disabled={!txData.txId || (!isPending && isReplacement && !txData.amount) || !txData.screenshot}
          >
            <i className="fas fa-check"></i> 
            {isPending ? 'Send to Customer Care' : 'Submit'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default TransactionForm;
